class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        def ipv4(parts: List[str]) -> bool:
            return len(parts) == 4 and all(
                p.isascii() and p.isdigit() and len(p) <= 3 and int(p) <= 255 and (p == "0" or p[0] != "0")
                for p in parts
            )

        def ipv6(parts: List[str]) -> bool:
            hexdigits = set("0123456789abcdefABCDEF")
            return len(parts) == 8 and all(1 <= len(p) <= 4 and all(ch in hexdigits for ch in p) for p in parts)

        if "." in queryIP and ipv4(queryIP.split(".")):
            return "IPv4"
        if ":" in queryIP and ipv6(queryIP.split(":")):
            return "IPv6"
        return "Neither"
